// golang against golang.org/x/mod v0.42.0 (testdata/oracle, generated by scripts/oracle), the test
// tables of x/mod's semver and module packages (testdata/x-mod), and the osv-scalibr semver vectors.
import { describe, expect, it } from 'vitest'
import { contains, getScheme, parseVers, type Scheme, VersError } from '../../src/index.ts'
import { expectTotalOrder, oracleValidity, SIGN } from '../support/oracle.ts'
import { loadComparisonPairs, readTestdata } from '../support/vectors.ts'

const s = getScheme('golang') as Scheme

const stripV = (v: string): string => (v.startsWith('v') ? v.slice(1) : v)

/** Asserts that each group holds equal versions and the groups are in strictly ascending order. */
function expectOrder(groups: string[][]): void {
  const ranked = groups.flatMap((g, rank) => g.map((v) => [v, rank] as const))
  for (const [a, i] of ranked) {
    for (const [b, j] of ranked) {
      expect(Math.sign(s.compare(a, b)), `${a} vs ${b}`).toBe(Math.sign(i - j))
    }
  }
}

describe('golang against x/mod', () => {
  const valid = oracleValidity('golang')
  const pairs = loadComparisonPairs('oracle/golang.txt')

  it('agrees on validity', () => {
    const wrong = valid
      .filter(([v, ok]) => v.startsWith('v') && s.isValid(v) !== ok)
      .map(([v, ok]) => `${v} (x/mod: ${ok ? 'valid' : 'invalid'})`)
    expect(wrong).toEqual([])
  })

  it('accepts a version without "v" exactly when x/mod accepts it with "v"', () => {
    const wrong = valid
      .filter(([v]) => !v.startsWith('v') && s.isValid(v) !== s.isValid(`v${v}`))
      .map(([v]) => v)
    expect(wrong).toEqual([])
  })

  it('agrees on every comparison', () => {
    const wrong = pairs
      .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
      .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
    expect(wrong).toEqual([])
  })

  it('agrees on every comparison without "v"', () => {
    const wrong = pairs
      .filter(({ a, op, b }) => Math.sign(s.compare(stripV(a), stripV(b))) !== SIGN[op])
      .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
    expect(wrong).toEqual([])
  })

  it('is a total order', () => {
    const sample = valid.filter(([, ok]) => ok).map(([v]) => v)
    expectTotalOrder(
      s,
      sample.filter((_, i) => i % Math.ceil(sample.length / 400) === 0),
    )
  })
})

describe('x/mod test tables', () => {
  // semver_test.go's `tests`: an empty `out` marks an invalid version. TestCompare expects valid rows in
  // ascending table order, with equal canonical forms comparing equal. x/mod orders invalid versions
  // before valid ones, but polyver throws, so pairs with an invalid side are skipped.
  const rows = JSON.parse(readTestdata('x-mod/semver.json')) as { in: string; out: string }[]
  const pseudo = JSON.parse(readTestdata('x-mod/pseudo.json')) as {
    older: string
    version: string
  }[]

  it('agrees on validity', () => {
    const wrong = rows.filter((r) => s.isValid(r.in) !== (r.out !== '')).map((r) => r.in)
    expect(wrong).toEqual([])
  })

  it('agrees on every comparison (TestCompare)', () => {
    const wrong: string[] = []
    rows.forEach((x, i) => {
      rows.forEach((y, j) => {
        if (x.out === '' || y.out === '') return
        const want = x.out === y.out ? 0 : Math.sign(i - j)
        if (Math.sign(s.compare(x.in, y.in)) !== want) wrong.push(`${x.in} vs ${y.in}`)
      })
    })
    expect(wrong).toEqual([])
  })

  it.each(pseudo)('orders pseudo-version $version after its base and before its release', (p) => {
    expect(s.isValid(p.version)).toBe(true)
    if (p.older !== '') expect(s.compare(p.older, p.version)).toBeLessThan(0)
    const release = p.version.replace(/-[^+]*/, '')
    expect(s.compare(p.version, release)).toBeLessThan(0)
  })
})

describe('osv-scalibr vectors', () => {
  it('passes the pairs that are valid golang versions', () => {
    const used = loadComparisonPairs('osv-scalibr/semver-versions.txt').filter(
      ({ a, b }) => s.isValid(a) && s.isValid(b),
    )
    const wrong = used
      .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
      .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
    expect(wrong).toEqual([])
    expect(used.length).toBeGreaterThan(70)
  })
})

describe('validity', () => {
  it.each([
    'v1.2.3',
    '1.2.3',
    'v1',
    '1',
    'v1.2',
    'v0.0.0-20191109021931-daa7c04131f5',
    'v2.0.0+incompatible',
    'v1.0.0--',
    `v${'9'.repeat(30)}.0.0`,
  ])('accepts %s', (v) => expect(s.isValid(v)).toBe(true))

  it.each([
    '',
    'v',
    'V1.0.0',
    'vv1.0.0',
    'v1-pre',
    'v1.2+meta',
    'v01.0.0',
    'v1.0.0-01',
    'v1.0.0.0',
    'v1.0.0-',
    ' v1.0.0',
  ])('rejects %j', (v) => expect(s.isValid(v)).toBe(false))

  it('throws on an invalid version', () => {
    expect(() => s.compare('v1.0.0', 'latest')).toThrow(VersError)
  })
})

describe('order', () => {
  it('reads the shorthands and a missing "v" as the full version', () => {
    expectOrder([['v1.0.0-rc.1'], ['v1', 'v1.0', 'v1.0.0', '1', '1.0.0'], ['v1.2', '1.2.0']])
  })

  it('orders pseudo-versions by timestamp', () => {
    expectOrder([
      ['v1.2.3'],
      ['v1.2.4-0.20191109021931-daa7c04131f5'],
      ['v1.2.4-0.20240101120000-0123456789ab'],
      ['v1.2.4-rc.1'],
      ['v1.2.4'],
    ])
  })

  it('ignores build metadata such as +incompatible', () => {
    expectOrder([
      ['v2.0.0+incompatible', 'v2.0.0', '2.0.0+build.1'],
      ['v2.0.1-0.20191109021931-daa7c04131f5+incompatible'],
      ['v2.0.1+incompatible'],
    ])
  })
})

describe('VERS', () => {
  it('evaluates a range that mixes versions with and without "v"', () => {
    const vers = 'vers:golang/>=1.2.0|<v1.3.0'
    expect(contains(vers, 'v1.2.5-0.20240101000000-abcdef123456')).toBe(true)
    expect(contains(vers, '1.3.0-rc.1')).toBe(true)
    expect(contains(vers, 'v1.3')).toBe(false)
  })

  it('rejects a shorthand and its full form as duplicates', () => {
    expect(() => parseVers('vers:golang/v1|v1.0.0')).toThrow(VersError)
  })
})
